1	package com.example.starter.baggage;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.UUID;
6	import java.util.concurrent.Callable;
7	import java.util.concurrent.CountDownLatch;
8	import java.util.concurrent.ExecutorService;
9	import java.util.concurrent.Executors;
10	import java.util.concurrent.Future;
11	import java.util.concurrent.TimeUnit;
12	
13	import org.junit.jupiter.api.AfterEach;
14	import org.junit.jupiter.api.BeforeEach;
15	import org.junit.jupiter.api.Test;
16	import org.springframework.beans.factory.annotation.Autowired;
17	import org.springframework.boot.test.context.SpringBootTest;
18	import org.springframework.jdbc.core.JdbcTemplate;
19	
20	import com.example.starter.baggage.BaggageDtos.LoadRequest;
21	import com.example.starter.baggage.BaggageDtos.LoadResponse;
22	import com.example.starter.baggage.BaggageDtos.RegisterBagRequest;
23	import com.example.starter.baggage.BaggageDtos.RegisterLegRequest;
24	import com.example.starter.baggage.BaggageDtos.SealRequest;
25	import com.example.starter.baggage.BaggageDtos.SealResponse;
26	
27	import static org.assertj.core.api.Assertions.assertThat;
28	
29	/**
30	 * 并发边界测试：同件行李并发装载只进入一个清单；
31	 * 装载与封舱并发以版本决定唯一先后；同键并发重放结果一致且只生效一次。
32	 */
33	@SpringBootTest
34	class BaggageConcurrencyTest {
35	
36	    @Autowired
37	    private BaggageService baggageService;
38	
39	    @Autowired
40	    private JdbcTemplate jdbcTemplate;
41	
42	    private ExecutorService executor;
43	
44	    @BeforeEach
45	    void setUp() {
46	        jdbcTemplate.update("DELETE FROM bag_event");
47	        jdbcTemplate.update("DELETE FROM load_record");
48	        jdbcTemplate.update("DELETE FROM bag_itinerary");
49	        jdbcTemplate.update("DELETE FROM bag");
50	        jdbcTemplate.update("DELETE FROM leg");
51	        jdbcTemplate.update("DELETE FROM request_log");
52	        executor = Executors.newFixedThreadPool(8);
53	    }
54	
55	    @AfterEach
56	    void tearDown() throws InterruptedException {
57	        executor.shutdownNow();
58	        assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
59	    }
60	
61	    @Test
62	    void concurrentLoadSameBag_entersOnlyOneManifest() throws Exception {
63	        registerLeg("LEG1", "PEK", "SHA");
64	        registerBag("BAG1", List.of("LEG1"));
65	
66	        List<Callable<Object>> tasks = new ArrayList<>();
67	        for (int i = 0; i < 4; i++) {
68	            tasks.add(() -> baggageService.load("LEG1",
69	                    new LoadRequest(UUID.randomUUID().toString(), 1, List.of("BAG1"))));
70	        }
71	        List<Object> results = runConcurrently(tasks);
72	
73	        long successes = results.stream().filter(LoadResponse.class::isInstance).count();
74	        long conflicts = results.stream()
75	                .filter(ApiException.class::isInstance)
76	                .map(ApiException.class::cast)
77	                .filter(ex -> ex.getStatus().value() == 409)
78	                .count();
79	        assertThat(successes).isEqualTo(1);
80	        assertThat(conflicts).isEqualTo(3);
81	
82	        Integer records = jdbcTemplate.queryForObject(
83	                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
84	        assertThat(records).isEqualTo(1);
85	        Integer version = jdbcTemplate.queryForObject(
86	                "SELECT version FROM leg WHERE leg_id = 'LEG1'", Integer.class);
87	        assertThat(version).isEqualTo(2);
88	    }
89	
90	    @Test
91	    void concurrentLoadAndSeal_versionDecidesSingleWinner() throws Exception {
92	        registerLeg("LEG1", "PEK", "SHA");
93	        registerBag("BAG1", List.of("LEG1"));
94	        registerBag("BAG2", List.of("LEG1"));
95	        baggageService.load("LEG1", new LoadRequest(UUID.randomUUID().toString(), 1, List.of("BAG1")));
96	
97	        List<Callable<Object>> tasks = List.of(
98	                () -> baggageService.load("LEG1",
99	                        new LoadRequest(UUID.randomUUID().toString(), 2, List.of("BAG2"))),
100	                () -> baggageService.seal("LEG1",
101	                        new SealRequest(UUID.randomUUID().toString(), 2)));
102	        List<Object> results = runConcurrently(tasks);
103	
104	        long successes = results.stream()
105	                .filter(r -> r instanceof LoadResponse || r instanceof SealResponse)
106	                .count();
107	        long conflicts = results.stream()
108	                .filter(ApiException.class::isInstance)
109	                .map(ApiException.class::cast)
110	                .filter(ex -> ex.getStatus().value() == 409)
111	                .count();
112	        assertThat(successes).isEqualTo(1);
113	        assertThat(conflicts).isEqualTo(1);
114	
115	        String status = jdbcTemplate.queryForObject(
116	                "SELECT status FROM leg WHERE leg_id = 'LEG1'", String.class);
117	        Integer version = jdbcTemplate.queryForObject(
118	                "SELECT version FROM leg WHERE leg_id = 'LEG1'", Integer.class);
119	        assertThat(version).isEqualTo(3);
120	        if ("OPEN".equals(status)) {
121	            // 装载先成功：封舱可随后以新版本完成，清单包含两件行李
122	            SealResponse sealed = baggageService.seal("LEG1",
123	                    new SealRequest(UUID.randomUUID().toString(), 3));
124	            assertThat(sealed.manifest()).containsExactly("BAG1", "BAG2");
125	        } else {
126	            // 封舱先成功：清单只有 BAG1，封舱后不得加装
127	            assertThat(status).isEqualTo("SEALED");
128	            assertThat(baggageService.getManifest("LEG1").manifest()).containsExactly("BAG1");
129	        }
130	    }
131	
132	    @Test
133	    void concurrentSameRequestId_replaysSingleEffect() throws Exception {
134	        registerLeg("LEG1", "PEK", "SHA");
135	        registerBag("BAG1", List.of("LEG1"));
136	
137	        String requestId = UUID.randomUUID().toString();
138	        List<Callable<Object>> tasks = new ArrayList<>();
139	        for (int i = 0; i < 6; i++) {
140	            tasks.add(() -> baggageService.load("LEG1",
141	                    new LoadRequest(requestId, 1, List.of("BAG1"))));
142	        }
143	        List<Object> results = runConcurrently(tasks);
144	
145	        assertThat(results).allSatisfy(result -> {
146	            assertThat(result).isInstanceOf(LoadResponse.class);
147	            assertThat(((LoadResponse) result).version()).isEqualTo(2);
148	        });
149	        Integer version = jdbcTemplate.queryForObject(
150	                "SELECT version FROM leg WHERE leg_id = 'LEG1'", Integer.class);
151	        assertThat(version).isEqualTo(2);
152	        Integer records = jdbcTemplate.queryForObject(
153	                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
154	        assertThat(records).isEqualTo(1);
155	        Integer logs = jdbcTemplate.queryForObject(
156	                "SELECT COUNT(*) FROM request_log WHERE request_id = ?", Integer.class, requestId);
157	        assertThat(logs).isEqualTo(1);
158	    }
159	
160	    private void registerLeg(String legId, String origin, String destination) {
161	        baggageService.registerLeg(
162	                new RegisterLegRequest(UUID.randomUUID().toString(), legId, origin, destination));
163	    }
164	
165	    private void registerBag(String bagTag, List<String> legIds) {
166	        baggageService.registerBag(new RegisterBagRequest(UUID.randomUUID().toString(), bagTag, legIds));
167	    }
168	
169	    /** 同步起跑并发执行任务，结果按提交顺序返回（异常包装为返回值）。 */
170	    private List<Object> runConcurrently(List<Callable<Object>> tasks) throws Exception {
171	        CountDownLatch ready = new CountDownLatch(tasks.size());
172	        CountDownLatch start = new CountDownLatch(1);
173	        List<Future<Object>> futures = new ArrayList<>();
174	        for (Callable<Object> task : tasks) {
175	            futures.add(executor.submit(() -> {
176	                ready.countDown();
