        review("CK1", "D1", "agent-b").andExpect(status().isOk());
        release("CK1", "agent-b").andExpect(status().isOk());

        // 解除后历史不改写：链记录完整保留两位操作人与时刻，重复读取结果一致
        String first = mockMvc.perform(get("/api/bags/BAG1/claim-hold/history"))
