        // 行李轨迹包含冻结与解除事件
        mockMvc.perform(get("/api/bags/BAG1/trace"))
                .andExpect(jsonPath("$.events[1].eventType").value("CLAIM_HELD"))
                .andExpect(jsonPath("$.events[2].eventType").value("CLAIM_RELEASED"));
    }

